CREATE TABLE permisos (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nombre varchar(100) NOT NULL UNIQUE, descripcion varchar(255), modulo varchar(50) NOT NULL);
CREATE TABLE roles (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nombre varchar(50) NOT NULL UNIQUE, descripcion varchar(255));
CREATE TABLE roles_permisos (rol_id bigint NOT NULL REFERENCES roles(id), permiso_id bigint NOT NULL REFERENCES permisos(id), PRIMARY KEY(rol_id, permiso_id));
CREATE TABLE usuarios (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nombre varchar(100) NOT NULL, apellido varchar(100) NOT NULL, email varchar(150) NOT NULL UNIQUE, password varchar(255) NOT NULL, es_activo boolean, es_bloqueado boolean, intentos_fallidos integer, rol_id bigint REFERENCES roles(id), fecha_creacion timestamp(6));
CREATE TABLE sedes (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, codigo varchar(30) NOT NULL UNIQUE, nombre varchar(120) NOT NULL, direccion varchar(250) NOT NULL);
CREATE TABLE almacenes (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, codigo varchar(30) NOT NULL UNIQUE, nombre varchar(120) NOT NULL, sede_id bigint NOT NULL REFERENCES sedes(id));
CREATE TABLE categorias (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nombre varchar(100) NOT NULL UNIQUE, descripcion varchar(250));
CREATE TABLE productos (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, codigo varchar(30) NOT NULL UNIQUE, nombre varchar(120) NOT NULL, unidad_medida varchar(30) NOT NULL, stock_minimo integer NOT NULL CHECK(stock_minimo>=0), categoria_id bigint NOT NULL REFERENCES categorias(id));
CREATE TABLE existencias (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, producto_id bigint NOT NULL REFERENCES productos(id), almacen_id bigint NOT NULL REFERENCES almacenes(id), cantidad integer NOT NULL CHECK(cantidad>=0), version bigint, UNIQUE(producto_id,almacen_id));
CREATE TABLE movimientos (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, producto_id bigint NOT NULL REFERENCES productos(id), origen_id bigint REFERENCES almacenes(id), destino_id bigint NOT NULL REFERENCES almacenes(id), cantidad integer NOT NULL CHECK(cantidad>0), tipo varchar(20) NOT NULL, motivo varchar(200) NOT NULL, responsable varchar(150) NOT NULL, fecha timestamp(6) NOT NULL);
CREATE INDEX idx_movimientos_producto ON movimientos(producto_id);
CREATE INDEX idx_movimientos_fecha ON movimientos(fecha);
